const r=`<?xml version="1.0" encoding="utf-8"?>\r
<style xmlns="http://purl.org/net/xbiblio/csl" class="in-text" delimiter-precedes-last="always" demote-non-dropping-particle="sort-only" initialize-with="" initialize-with-hyphen="false" name-as-sort-order="all" name-delimiter=", " names-delimiter=", " page-range-format="minimal" sort-separator=" " version="1.0">\r
  <!-- This file was generated by the Style Variant Builder <https://github.com/citation-style-language/style-variant-builder>. To contribute changes, modify the template and regenerate variants. -->\r
  <info>\r
    <title>NLM/Vancouver: Citing Medicine 2nd edition (citation-sequence)</title>\r
    <title-short>National Library of Medicine, ANSI/NISO Z39.29-2005 (R2010), ICMJE Recommendations/URMs (C-S)</title-short>\r
    <id>http://www.zotero.org/styles/nlm-citation-sequence</id>\r
    <link href="http://www.zotero.org/styles/nlm-citation-sequence" rel="self"/>\r
    <link href="https://www.nlm.nih.gov/citingmedicine" rel="documentation"/>\r
    <link href="https://www.nlm.nih.gov/bsd/uniform_requirements.html" rel="documentation"/>\r
    <link href="https://www.icmje.org/recommendations/" rel="documentation"/>\r
    <author>\r
      <name>Michael Berkowitz</name>\r
      <email>mberkowi@gmu.edu</email>\r
    </author>\r
    <author>\r
      <name>Andrew Dunning</name>\r
      <uri>https://orcid.org/0000-0003-0464-5036</uri>\r
    </author>\r
    <contributor>\r
      <name>Petr Hlustik</name>\r
      <uri>https://orcid.org/0000-0002-1951-0671</uri>\r
    </contributor>\r
    <contributor>\r
      <name>Sebastian Karcher</name>\r
      <uri>https://orcid.org/0000-0001-8249-7388</uri>\r
    </contributor>\r
    <contributor>\r
      <name>Charles Parnot</name>\r
      <uri>https://orcid.org/0000-0002-7346-5883</uri>\r
    </contributor>\r
    <contributor>\r
      <name>Sean Takats</name>\r
      <uri>https://orcid.org/0000-0002-7851-5069</uri>\r
    </contributor>\r
    <category citation-format="numeric"/>\r
    <category field="generic-base"/>\r
    <category field="medicine"/>\r
    <category field="science"/>\r
    <summary>Citing Medicine: The NLM Style Guide for Authors, Editors, and Publishers, 2nd edition (2015), based on ANSI/NISO Z39.29-2005 (R2010); citation-sequence system.</summary>\r
    <updated>2026-01-07T00:00:00+00:00</updated>\r
    <rights license="http://creativecommons.org/licenses/by-sa/3.0/">This work is licensed under a Creative Commons Attribution-ShareAlike 3.0 License</rights>\r
  </info>\r
  <locale xml:lang="en">\r
    <date delimiter=" " form="text">\r
      <date-part name="year"/>\r
      <date-part form="short" name="month" strip-periods="true"/>\r
      <date-part name="day"/>\r
    </date>\r
    <terms>\r
      <term name="available at">available from</term>\r
      <term name="collection-editor">\r
        <single>editor</single>\r
        <multiple>editors</multiple>\r
      </term>\r
      <term form="short" name="month-06">Jun.</term>\r
      <term form="short" name="month-07">Jul.</term>\r
      <term form="short" name="month-09">Sep.</term>\r
      <term name="presented at">presented at</term>\r
      <term form="short" name="section">\r
        <single>sect.</single>\r
        <multiple>sects.</multiple>\r
      </term>\r
      <term form="short" name="supplement">\r
        <single>suppl.</single>\r
        <multiple>suppls.</multiple>\r
      </term>\r
    </terms>\r
  </locale>\r
  <locale xml:lang="fr">\r
    <date delimiter=" " form="text">\r
      <date-part name="day"/>\r
      <date-part form="short" name="month" strip-periods="true"/>\r
      <date-part name="year"/>\r
    </date>\r
  </locale>\r
  <!-- Variable labels -->\r
  <macro name="label-collection-number">\r
    <group delimiter=" ">\r
      <choose>\r
        <if is-numeric="collection-number">\r
          <label form="short" variable="collection-number"/>\r
        </if>\r
      </choose>\r
      <text variable="collection-number"/>\r
    </group>\r
  </macro>\r
  <macro name="label-edition">\r
    <group delimiter=" ">\r
      <choose>\r
        <if is-numeric="edition">\r
          <number form="ordinal" variable="edition"/>\r
          <label form="short" variable="edition"/>\r
        </if>\r
        <else>\r
          <text variable="edition"/>\r
        </else>\r
      </choose>\r
    </group>\r
  </macro>\r
  <macro name="label-number">\r
    <group delimiter=": ">\r
      <choose>\r
        <if type="standard"/>\r
        <else-if is-numeric="number" match="any" type="legislation patent regulation">\r
          <label form="short" variable="number"/>\r
        </else-if>\r
      </choose>\r
      <text variable="number"/>\r
    </group>\r
  </macro>\r
  <macro name="label-number-of-pages">\r
    <group delimiter=" ">\r
      <text variable="number-of-pages"/>\r
      <choose>\r
        <if is-numeric="number-of-pages">\r
          <label form="short" plural="never" variable="number-of-pages"/>\r
        </if>\r
      </choose>\r
    </group>\r
  </macro>\r
  <macro name="label-page">\r
    <group delimiter=" ">\r
      <label form="short" plural="never" variable="page"/>\r
      <text variable="page"/>\r
    </group>\r
  </macro>\r
  <macro name="label-part-number-capitalized">\r
    <group delimiter=" ">\r
      <choose>\r
        <if is-numeric="part-number">\r
          <!-- TODO: Replace with \`part-number\` label when CSL provides one -->\r
          <text form="short" term="part" text-case="capitalize-first"/>\r
        </if>\r
      </choose>\r
      <text variable="part-number"/>\r
    </group>\r
  </macro>\r
  <macro name="label-supplement-number">\r
    <group delimiter=" ">\r
      <choose>\r
        <if is-numeric="supplement-number">\r
          <!-- TODO: Replace with \`supplement-number\` label when CSL provides one -->\r
          <text form="short" strip-periods="true" term="supplement" text-case="capitalize-first"/>\r
        </if>\r
      </choose>\r
      <text text-case="capitalize-first" variable="supplement-number"/>\r
    </group>\r
  </macro>\r
  <macro name="label-volume-capitalized">\r
    <group delimiter=" ">\r
      <choose>\r
        <if is-numeric="volume">\r
          <label form="short" text-case="capitalize-first" variable="volume"/>\r
        </if>\r
      </choose>\r
      <text variable="volume"/>\r
    </group>\r
  </macro>\r
  <macro name="author">\r
    <names variable="author">\r
      <label prefix=", "/>\r
      <substitute>\r
        <names variable="editor-translator"/>\r
        <names variable="editor translator"/>\r
        <names variable="editor"/>\r
        <names variable="collection-editor"/>\r
      </substitute>\r
    </names>\r
  </macro>\r
  <macro name="title">\r
    <choose>\r
      <if type="webpage" variable="container-title">\r
        <!-- \`webpage\` listed under \`container-title\` (Citing Medicine, ch. 25) -->\r
        <text variable="container-title"/>\r
      </if>\r
      <else>\r
        <text variable="title"/>\r
      </else>\r
    </choose>\r
  </macro>\r
  <macro name="content-type">\r
    <text variable="genre"/>\r
  </macro>\r
  <macro name="type-of-medium">\r
    <choose>\r
      <if variable="medium">\r
        <text text-case="capitalize-first" variable="medium"/>\r
      </if>\r
      <else-if match="any" type="chapter entry-dictionary entry-encyclopedia paper-conference"/>\r
      <else-if variable="URL">\r
        <text term="internet" text-case="capitalize-first"/>\r
      </else-if>\r
    </choose>\r
  </macro>\r
  <macro name="container-preposition">\r
    <choose>\r
      <if match="any" type="chapter paper-conference entry-dictionary entry-encyclopedia">\r
        <text term="in" text-case="capitalize-first"/>\r
      </if>\r
    </choose>\r
  </macro>\r
  <macro name="secondary-authors">\r
    <names variable="editor">\r
      <label prefix=", "/>\r
    </names>\r
  </macro>\r
  <macro name="container-title">\r
    <group delimiter=", ">\r
      <choose>\r
        <if type="webpage"/>\r
        <else-if variable="container-title">\r
          <group delimiter=". ">\r
            <group delimiter=" ">\r
              <choose>\r
                <if match="any" type="article-journal review review-book">\r
                  <text form="short" strip-periods="true" variable="container-title"/>\r
                </if>\r
                <else>\r
                  <text variable="container-title"/>\r
                </else>\r
              </choose>\r
              <choose>\r
                <if type="article-journal" variable="DOI"/>\r
                <else-if type="article-journal" variable="PMID"/>\r
                <else-if type="article-journal" variable="PMCID"/>\r
                <else-if variable="URL">\r
                  <text prefix="[" suffix="]" term="internet" text-case="capitalize-first"/>\r
                </else-if>\r
              </choose>\r
            </group>\r
            <text macro="label-edition"/>\r
          </group>\r
        </else-if>\r
        <!-- TODO: add \`event-name\` and \`event-place\` -->\r
        <else-if match="any" type="bill legislation">\r
          <group delimiter=". ">\r
            <text variable="container-title"/>\r
            <group delimiter=" ">\r
              <text form="short" term="section" text-case="capitalize-first"/>\r
              <text variable="section"/>\r
            </group>\r
          </group>\r
          <text variable="number"/>\r
        </else-if>\r
        <else-if type="speech">\r
          <group delimiter=": ">\r
            <group delimiter=" ">\r
              <text text-case="capitalize-first" variable="genre"/>\r
              <text term="presented at"/>\r
            </group>\r
            <text variable="event"/>\r
          </group>\r
        </else-if>\r
        <else>\r
          <group delimiter=", ">\r
            <text macro="label-volume-capitalized"/>\r
            <text variable="volume-title"/>\r
          </group>\r
          <group delimiter=", ">\r
            <text macro="label-part-number-capitalized"/>\r
            <text variable="part-title"/>\r
          </group>\r
        </else>\r
      </choose>\r
    </group>\r
  </macro>\r
  <macro name="place-of-publication">\r
    <choose>\r
      <if type="thesis">\r
        <text prefix="[" suffix="]" variable="publisher-place"/>\r
      </if>\r
      <else-if type="speech"/>\r
      <else>\r
        <text variable="publisher-place"/>\r
      </else>\r
    </choose>\r
  </macro>\r
  <macro name="publisher">\r
    <choose>\r
      <!-- discard publisher for serial publications -->\r
      <if match="none" type="article-journal article-magazine article-newspaper periodical post-weblog review review-book">\r
        <group delimiter=": ">\r
          <text macro="place-of-publication"/>\r
          <text variable="publisher"/>\r
        </group>\r
      </if>\r
    </choose>\r
  </macro>\r
  <macro name="date">\r
    <group delimiter=" ">\r
      <choose>\r
        <if match="any" type="article-journal article-magazine article-newspaper periodical post-weblog review review-book">\r
          <group delimiter=":">\r
            <group delimiter=" ">\r
              <date form="text" variable="issued"/>\r
              <choose>\r
                <if type="article-journal" variable="DOI"/>\r
                <else-if type="article-journal" variable="PMID"/>\r
                <else-if type="article-journal" variable="PMCID"/>\r
                <else>\r
                  <text macro="date-of-citation"/>\r
                </else>\r
              </choose>\r
            </group>\r
            <choose>\r
              <if type="article-newspaper">\r
                <text variable="page"/>\r
              </if>\r
            </choose>\r
          </group>\r
        </if>\r
        <else-if match="any" type="bill legislation">\r
          <date form="text" variable="issued"/>\r
        </else-if>\r
        <else-if type="report">\r
          <date date-parts="year-month" form="text" variable="issued"/>\r
          <text macro="date-of-citation"/>\r
        </else-if>\r
        <else-if type="patent">\r
          <group delimiter=", ">\r
            <text variable="number"/>\r
            <date date-parts="year" form="numeric" variable="issued"/>\r
          </group>\r
          <text macro="date-of-citation"/>\r
        </else-if>\r
        <else-if type="speech">\r
          <group delimiter="; ">\r
            <group delimiter=" ">\r
              <date form="text" variable="issued"/>\r
              <text macro="date-of-citation"/>\r
            </group>\r
            <text variable="event-place"/>\r
          </group>\r
        </else-if>\r
        <else>\r
          <date date-parts="year" form="numeric" variable="issued"/>\r
          <text macro="date-of-citation"/>\r
        </else>\r
      </choose>\r
    </group>\r
  </macro>\r
  <macro name="identifier-serial">\r
    <choose>\r
      <if match="any" type="article-journal article-magazine periodical post-weblog review review-book">\r
        <group delimiter=":">\r
          <group>\r
            <text variable="collection-title"/>\r
            <text variable="volume"/>\r
            <group delimiter=" " prefix="(" suffix=")">\r
              <text variable="issue"/>\r
              <text macro="label-supplement-number"/>\r
            </group>\r
          </group>\r
          <text macro="location-pagination-serial"/>\r
        </group>\r
      </if>\r
    </choose>\r
  </macro>\r
  <macro name="date-of-citation">\r
    <choose>\r
      <if variable="URL">\r
        <group delimiter=" " prefix="[" suffix="]">\r
          <text term="cited"/>\r
          <date form="text" variable="accessed"/>\r
        </group>\r
      </if>\r
    </choose>\r
  </macro>\r
  <macro name="location-pagination-monographic">\r
    <group delimiter=" ">\r
      <choose>\r
        <if match="any" type="article-journal article-magazine article-newspaper review review-book"/>\r
        <else-if type="book">\r
          <text macro="label-number-of-pages"/>\r
        </else-if>\r
        <else>\r
          <text macro="label-page"/>\r
        </else>\r
      </choose>\r
    </group>\r
  </macro>\r
  <macro name="location-pagination-serial">\r
    <choose>\r
      <if variable="number">\r
        <text variable="number"/>\r
      </if>\r
      <else>\r
        <text variable="page"/>\r
      </else>\r
    </choose>\r
  </macro>\r
  <macro name="webpage-part">\r
    <choose>\r
      <if type="webpage" variable="container-title">\r
        <text variable="title"/>\r
      </if>\r
    </choose>\r
  </macro>\r
  <macro name="series">\r
    <choose>\r
      <if match="any" type="article-journal article-magazine article-newspaper periodical post-weblog review review-book"/>\r
      <else-if variable="collection-title">\r
        <group delimiter=". " prefix="(" suffix=")">\r
          <names variable="collection-editor">\r
            <label prefix=", "/>\r
          </names>\r
          <group delimiter="; ">\r
            <text variable="collection-title"/>\r
            <text macro="label-collection-number"/>\r
          </group>\r
        </group>\r
      </else-if>\r
    </choose>\r
  </macro>\r
  <macro name="report-number">\r
    <choose>\r
      <if type="report" variable="number">\r
        <group delimiter=" ">\r
          <choose>\r
            <if variable="genre">\r
              <text text-case="capitalize-first" variable="genre"/>\r
            </if>\r
            <else>\r
              <text term="report" text-case="capitalize-first"/>\r
            </else>\r
          </choose>\r
          <text macro="label-number"/>\r
        </group>\r
      </if>\r
    </choose>\r
  </macro>\r
  <macro name="availability">\r
    <group delimiter=". ">\r
      <group delimiter=": ">\r
        <text text-case="capitalize-first" value="located at"/>\r
        <group delimiter="; ">\r
          <group delimiter=", ">\r
            <text variable="archive_collection"/>\r
            <text variable="archive"/>\r
            <text variable="archive-place"/>\r
          </group>\r
          <text variable="archive_location"/>\r
        </group>\r
      </group>\r
      <group delimiter=" ">\r
        <choose>\r
          <if type="article-journal" variable="DOI"/>\r
          <else-if type="article-journal" variable="PMID"/>\r
          <else-if type="article-journal" variable="PMCID"/>\r
          <else>\r
            <group delimiter=": ">\r
              <text term="available at" text-case="capitalize-first"/>\r
              <text variable="URL"/>\r
            </group>\r
          </else>\r
        </choose>\r
        <text prefix="doi:" variable="DOI"/>\r
      </group>\r
    </group>\r
  </macro>\r
  <macro name="notes">\r
    <group delimiter=". " suffix=".">\r
      <group delimiter="; ">\r
        <group delimiter=": ">\r
          <text value="PubMed PMID"/>\r
          <text variable="PMID"/>\r
        </group>\r
        <group delimiter=": ">\r
          <text value="PubMed Central PMCID"/>\r
          <text variable="PMCID"/>\r
        </group>\r
      </group>\r
      <text variable="references"/>\r
    </group>\r
  </macro>\r
  <citation collapse="citation-number">\r
    <sort>\r
      <key variable="citation-number"/>\r
    </sort>\r
    <layout delimiter="," prefix="(" suffix=")">\r
      <text variable="citation-number"/>\r
    </layout>\r
  </citation>\r
  <macro name="bibliography">\r
    <group delimiter=" ">\r
      <group delimiter=". " suffix=".">\r
        <text macro="author"/>\r
        <group delimiter=" ">\r
          <text macro="title"/>\r
          <text macro="content-type" prefix="[" suffix="]"/>\r
          <choose>\r
            <if type="webpage" variable="container-title">\r
              <text macro="type-of-medium" prefix="[" suffix="]"/>\r
            </if>\r
            <else-if match="none" variable="container-title">\r
              <text macro="type-of-medium" prefix="[" suffix="]"/>\r
            </else-if>\r
          </choose>\r
        </group>\r
        <choose>\r
          <if match="none" variable="container-title">\r
            <text macro="label-edition"/>\r
          </if>\r
        </choose>\r
        <group delimiter=": ">\r
          <text macro="container-preposition"/>\r
          <group delimiter=". ">\r
            <text macro="secondary-authors"/>\r
            <text macro="container-title"/>\r
          </group>\r
        </group>\r
        <group delimiter="; ">\r
          <text macro="publisher"/>\r
          <group delimiter=";">\r
            <text macro="date"/>\r
            <text macro="identifier-serial"/>\r
          </group>\r
        </group>\r
        <text macro="location-pagination-monographic"/>\r
        <text macro="webpage-part"/>\r
        <text macro="series"/>\r
        <text macro="report-number"/>\r
      </group>\r
      <text macro="availability"/>\r
      <text macro="notes"/>\r
    </group>\r
  </macro>\r
  <bibliography et-al-min="7" et-al-use-first="6" second-field-align="flush">\r
    <layout>\r
      <text suffix="." variable="citation-number"/>\r
      <text macro="bibliography"/>\r
    </layout>\r
  </bibliography>\r
</style>\r
`;export{r as default};
